import json, os
base = os.path.dirname(os.path.abspath(__file__))
outdir = os.path.join(base, "predictions")
os.makedirs(outdir, exist_ok=True)

P = {}

def add(cid, pred, basis, conf, trig, systems=None):
    P[cid] = {
        "case_id": cid,
        "prediction_text": pred,
        "basis": basis,
        "confidence": conf,
        "trigger": {"changed_main": trig[0], "reserve_used": trig[1], "disputed": trig[2], "reason": trig[3]},
        "systems_used": systems or ["liuyao"],
    }

